def transform(grid):
    from collections import Counter, deque

    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue

            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()

            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)

            if bottom - top < 2 or right - left < 2:
                continue

            perimeter = {
                (y, x)
                for y in range(top, bottom + 1)
                for x in range(left, right + 1)
                if y in (top, bottom) or x in (left, right)
            }
            if cells != perimeter:
                continue

            area = (bottom - top - 1) * (right - left - 1)
            fill = 7 if area % 2 else 2
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    if grid[y][x] == background:
                        out[y][x] = fill

    return out
